const int maxn = 2e5 + 5;
const int LOG = 20; 
vector<pair<int,int>> adj[maxn]; 
int par[maxn], sz[maxn];
int up[maxn][LOG];        
int maxw[maxn][LOG];      
int depth[maxn];

void init(int n) {
    for(int i = 1; i <= n; i++) {
        par[i] = i;
        sz[i] = 1;
        depth[i] = 0;
        for(int j = 0; j < LOG; j++) {
            up[i][j] = 0;
            maxw[i][j] = 0;
        }
        adj[i].clear();
    }
}

int find_par(int u) {
    return (par[u] == u ? u : par[u] = find_par(par[u]));
}

void unite(int u, int v) {
    int pu = find_par(u);
    int pv = find_par(v);
    if(pu != pv) {
        if(sz[pu] < sz[pv]) swap(pu, pv);
        par[pv] = pu;
        sz[pu] += sz[pv];
    }
}

void dfs(int u, int p) {
    for(auto &[v, w] : adj[u]) {
        if(v == p) continue;
        depth[v] = depth[u] + 1;
        up[v][0] = u;
        maxw[v][0] = w;
        for(int k = 1; k < LOG; k++) {
            up[v][k] = up[up[v][k-1]][k-1];
            maxw[v][k] = max(maxw[v][k-1], maxw[up[v][k-1]][k-1]);
        }
        dfs(v, u);
    }
}

int get_max(int u, int v) {
    if(depth[u] < depth[v]) swap(u, v);
    int res = 0;

    for(int k = LOG-1; k >= 0; k--) {
        if(depth[u] - (1<<k) >= depth[v]) {
            res = max(res, maxw[u][k]);
            u = up[u][k];
        }
    }
    if(u == v) return res;

    for(int k = LOG-1; k >= 0; k--) {
        if(up[u][k] != up[v][k]) {
            res = max(res, maxw[u][k]);
            res = max(res, maxw[v][k]);
            u = up[u][k];
            v = up[v][k];
        }
    }
    res = max(res, maxw[u][0]);
    res = max(res, maxw[v][0]);
    return res;
}

int main () {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    init(n);

    vector<tuple<int,int,int,int>> edges; 
    for(int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        edges.emplace_back(w, u, v, i);
    }

    sort(edges.begin(), edges.end());
    vector<long long> ans(m);
    vector<bool> in_mst(m, false);
    long long mst_weight = 0;

    for(auto &[w, u, v, idx] : edges) {
        if(find_par(u) != find_par(v)) {
            unite(u, v);
            mst_weight += w;
            in_mst[idx] = true;
            adj[u].emplace_back(v, w);
            adj[v].emplace_back(u, w);
        }
    }

    dfs(1, 0);

    for(auto &[w, u, v, idx] : edges) {
        if(in_mst[idx]) {
            ans[idx] = mst_weight;
        } else {
            int max_edge = get_max(u, v);
            ans[idx] = mst_weight + w - max_edge;
        }
    }

    for(int i = 0; i < m; i++) cout << ans[i] << "\n";
}